<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Models\{Sale,Purchase,Expense,Product};
class ReportController extends Controller{public function index(Request $r){$from=$r->from?:now()->startOfMonth()->toDateString();$to=$r->to?:today()->toDateString();$sales=Sale::whereBetween(DB::raw('DATE(sold_at)'),[$from,$to])->sum('total');$purchases=Purchase::whereBetween(DB::raw('DATE(purchased_at)'),[$from,$to])->sum('total');$expenses=Expense::whereBetween('expense_date',[$from,$to])->sum('amount');$rows=DB::table('sale_items')->join('sales','sales.id','=','sale_items.sale_id')->select('sale_items.business_unit_id',DB::raw('SUM(sale_items.line_total) as revenue'),DB::raw('SUM(sale_items.quantity*sale_items.unit_cost) as cost'),DB::raw('SUM(sale_items.line_total-sale_items.quantity*sale_items.unit_cost) as gross_profit'))->whereBetween(DB::raw('DATE(sales.sold_at)'),[$from,$to])->groupBy('sale_items.business_unit_id')->get();$lowStock=Product::with(['stock','baseUnit'])->whereHas('stock',fn($q)=>$q->whereColumn('quantity','<=','products.alert_quantity'))->get();$top=DB::table('sale_items')->join('sales','sales.id','=','sale_items.sale_id')->select('product_name',DB::raw('SUM(quantity) as qty'),DB::raw('SUM(line_total) as revenue'))->whereBetween(DB::raw('DATE(sales.sold_at)'),[$from,$to])->groupBy('product_name')->orderByDesc('revenue')->limit(10)->get();return view('reports.index',compact('from','to','sales','purchases','expenses','rows','lowStock','top'));}}
